#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    auto T0=chrono::steady_clock::now();
    auto elapsed=[&](){return chrono::duration<double>(chrono::steady_clock::now()-T0).count();};

    int N; cin>>N;
    vector<double> cx(N),cy(N);
    for(int i=0;i<N;i++) cin>>cx[i]>>cy[i];

    vector<bool> isp(N,false);
    {
        vector<bool> sieve(N,true);
        if(N>0) sieve[0]=false;
        if(N>1) sieve[1]=false;
        for(int i=2;(long long)i*i<N;i++)
            if(sieve[i]) for(int j=i*i;j<N;j+=i) sieve[j]=false;
        for(int i=0;i<N;i++) isp[i]=sieve[i];
    }

    auto dist=[&](int a,int b)->double{
        double dx=cx[a]-cx[b],dy=cy[a]-cy[b];
        return sqrt(dx*dx+dy*dy);
    };

    // step s (1-indexed): from tour[s-1] to tour[s]
    auto mult=[&](int step,int src)->double{
        return (step%10==0 && !isp[src])?1.1:1.0;
    };

    auto tourCost=[&](vector<int>&t)->double{
        double c=0;
        for(int s=1;s<=N;s++) c+=dist(t[s-1],t[s])*mult(s,t[s-1]);
        return c;
    };

    // Nearest neighbor
    auto buildNN=[&](int start)->vector<int>{
        vector<int> t(N+1);
        vector<bool> vis(N,false);
        t[0]=start; vis[start]=true;
        for(int step=1;step<N;step++){
            int last=t[step-1],best=-1;double bd=1e30;
            for(int j=0;j<N;j++) if(!vis[j]){double d=dist(last,j);if(d<bd){bd=d;best=j;}}
            t[step]=best; vis[best]=true;
        }
        t[N]=start;
        return t;
    };

    auto rotateToZero=[&](vector<int>&t){
        int zp=0;
        for(int i=0;i<N;i++) if(t[i]==0){zp=i;break;}
        vector<int> r(N+1);
        for(int i=0;i<N;i++) r[i]=t[(zp+i)%N];
        r[N]=0;
        t=r;
    };

    vector<int> best;double bestC=1e30;
    int tries=max(1,min(N<=1000?20:N<=3000?5:2,N));
    for(int tr=0;tr<tries&&elapsed()<0.5;tr++){
        auto t=buildNN(tr==0?0:tr%N);
        rotateToZero(t);
        double c=tourCost(t);
        if(c<bestC){bestC=c;best=t;}
    }

    vector<int>&tour=best;
    double curCost=bestC;

    // 2-opt with proper penalty recalc
    int W=min(N-1, N<=2000?200:N<=5000?80:40);

    for(int pass=0;pass<100&&elapsed()<1.9;pass++){
        bool imp=false;
        for(int i=1;i<N&&elapsed()<1.85;i++){
            for(int j=i+1;j<=min(i+W,N-1);j++){
                // reverse tour[i..j]
                int lo=i,hi=j+1;
                double oldC=0;
                for(int s=lo;s<=min(hi,N);s++) oldC+=dist(tour[s-1],tour[s])*mult(s,tour[s-1]);
                reverse(tour.begin()+i,tour.begin()+j+1);
                double newC=0;
                for(int s=lo;s<=min(hi,N);s++) newC+=dist(tour[s-1],tour[s])*mult(s,tour[s-1]);
                if(newC<oldC-1e-10){
                    curCost+=newC-oldC;
                    imp=true;
                } else {
                    reverse(tour.begin()+i,tour.begin()+j+1);
                }
            }
        }
        if(!imp) break;
    }

    // Or-opt: move single city
    for(int pass=0;pass<50&&elapsed()<1.9;pass++){
        bool imp=false;
        for(int i=1;i<N&&elapsed()<1.85;i++){
            int city=tour[i];
            int lo0=i,hi0=i+1;
            double remOld=0;
            for(int s=lo0;s<=min(hi0,N);s++) remOld+=dist(tour[s-1],tour[s])*mult(s,tour[s-1]);
            double remNew=dist(tour[i-1],tour[i+1])*mult(i,tour[i-1]);
            double remDelta=remNew-remOld;// cost change from removal (partial)
            // But shifting changes step assignments. Recompute fully for small window.

            double bestD=0;int bestJ=-1;
            int R=min(60,N-1);
            for(int j=max(1,i-R);j<=min(N-1,i+R);j++){
                if(j==i||j==i-1) continue;
                int lo=min(i,j),hi=max(i,j)+1;
                double oldC=0;
                for(int s=lo;s<=min(hi,N);s++) oldC+=dist(tour[s-1],tour[s])*mult(s,tour[s-1]);
                // apply move
                int c2=tour[i];
                vector<int> backup(tour.begin()+lo-1,tour.begin()+min(hi+2,N+1));
                if(j>i){for(int k=i;k<j;k++)tour[k]=tour[k+1];tour[j]=c2;}
                else{for(int k=i;k>j;k--)tour[k]=tour[k-1];tour[j]=c2;}
                double newC=0;
                for(int s=lo;s<=min(hi,N);s++) newC+=dist(tour[s-1],tour[s])*mult(s,tour[s-1]);
                double delta=newC-oldC;
                // undo
                for(int k=0;k<(int)backup.size();k++) tour[lo-1+k]=backup[k];
                if(delta<bestD-1e-10){bestD=delta;bestJ=j;}
            }
            if(bestJ>=0){
                int c2=tour[i];
                if(bestJ>i){for(int k=i;k<bestJ;k++)tour[k]=tour[k+1];tour[bestJ]=c2;}
                else{for(int k=i;k>bestJ;k--)tour[k]=tour[k-1];tour[bestJ]=c2;}
                curCost+=bestD;
                imp=true;
            }
        }
        if(!imp) break;
    }

    cout<<N+1<<"\n";
    for(int i=0;i<=N;i++) cout<<tour[i]<<"\n";
}
